import React, { useState } from 'react';
import './Research.css';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import PublicationItem from '../components/PublicationItem';
import publicationsData, { publicationFilters, matchesFilter } from '../data/publications';

function Research() {
  const [filter, setFilter] = useState('all');

  const visiblePublications = publicationsData.filter((publication) =>
    matchesFilter(publication, filter)
  );

  return (
    <>
      <Navbar />
      <div className='research-container'>
        <div className='research-header'>
          <h1>Research</h1>
        </div>

        {/* Unified research list (conference, workshop, preprint, project) */}
        <div className='research-section'>
          <div className='research-toggle'>
            <div
              className='segmented'
              role='group'
              aria-label='Filter publications'
              style={{
                '--count': publicationFilters.length,
                '--index': publicationFilters.findIndex((option) => option.key === filter),
              }}
            >
              {publicationFilters.map((option) => (
                <button
                  key={option.key}
                  className={`segmented__btn ${filter === option.key ? 'segmented__btn--active' : ''}`}
                  aria-pressed={filter === option.key}
                  onClick={() => setFilter(option.key)}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>
          <div className='research-list'>
            {visiblePublications.map((publication) => (
              <PublicationItem
                key={publication.id}
                publication={publication}
              />
            ))}
            {filter === 'all' && (
              <p style={{ color: 'var(--text-color-secondary)', fontStyle: 'italic', marginTop: '20px' }}>More under review</p>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </>
  );
}

export default Research;
